#include <iostream>
#include <fstream>
#include <sstream>
#include <vector>
#include <set>
#include <iomanip>
#include <stack>
#include <algorithm>
using namespace std;

/**
 * Description: 各类函数与结构体定义
 * Author: 杜登宇
 */

//加载文件
string load_file(string file_name);

//定义规则结构体
struct rule {
	char left;
	vector<string> right;
	friend ostream& operator << (ostream& out, rule rule);
};
//从文本提取规则、终结符、非终结符、右部
void split_into_rules(const string text, vector<rule>& rules, set<char>& non_terminal, set<char>& terminal, set<string>& right_parts);
//检查规则情况
void check_rules(const vector<rule> rules);
//检查set集情况
template <class T>
void check_set(set<T> set_, string tip);

//定义F（irst/ollow）集结构体
struct F_set {
	bool is_first;
	string left;
	set<char> right;
	friend ostream& operator << (ostream& out, F_set f_set);
};
//查找First集
F_set findFirst(const string right_part, vector<rule> rules);
//查找Follow集
F_set findFollow(const char non_terminal, vector<rule> rules);
//输出一个set集合里存放的字符对应的First集集合
vector<F_set> checkFirst(set<string> right_parts, vector<rule> rules);
//输出一个set集合里存放的字符对应的Follow集集合
vector<F_set> checkFollow(set<char> non_terminal, vector<rule> rules);

//定义LL（1）分析表结构体
struct LL_1_table {
	vector<char> row;
	vector<char> col;
	vector<rule> rules;
	friend ostream& operator << (ostream& out, LL_1_table table);
};
//分析表构建
LL_1_table LL_1(set<char>& terminal, set<char>& non_terminal, vector<rule> rules);
void print_state(stack<char> analysis_s, stack<char> input_s, rule& rule_temp);

//根据分析表进行语法分析
void syntacticAnalysis(LL_1_table table);

namespace {
int table_index(const vector<char>& values, char target) {
	vector<char>::const_iterator it = find(values.begin(), values.end(), target);
	if (it == values.end()) {
		return -1;
	}
	return static_cast<int>(distance(values.begin(), it));
}

vector<char> ordered_rows(const set<char>& non_terminal, const vector<rule>& rules) {
	vector<char> rows;
	set<char> seen;
	for (size_t i = 0; i < rules.size(); ++i) {
		if (seen.insert(rules[i].left).second) {
			rows.push_back(rules[i].left);
		}
	}
	for (set<char>::const_iterator it = non_terminal.begin(); it != non_terminal.end(); ++it) {
		if (seen.insert(*it).second) {
			rows.push_back(*it);
		}
	}
	return rows;
}

F_set findFirstInternal(const string& ss, const vector<rule>& rules, set<string>& active) {
	F_set f_set;
	f_set.is_first = true;
	f_set.left = ss;
	if (ss.empty()) {
		f_set.right.insert('@');
		return f_set;
	}

	for (size_t i = 0; i < ss.size(); ++i) {
		char current = ss[i];
		if (!isupper(static_cast<unsigned char>(current))) {
			f_set.right.insert(current);
			return f_set;
		}

		bool nullable = false;
		string key(1, current);
		if (active.count(key)) {
			return f_set;
		}
		active.insert(key);
		for (size_t r = 0; r < rules.size(); ++r) {
			if (rules[r].left != current) {
				continue;
			}
			for (size_t j = 0; j < rules[r].right.size(); ++j) {
				const string& right_part = rules[r].right[j];
				if (right_part == "@") {
					nullable = true;
					continue;
				}
				F_set temp = findFirstInternal(right_part, rules, active);
				bool right_nullable = false;
				for (set<char>::iterator it = temp.right.begin(); it != temp.right.end(); ++it) {
					if (*it == '@') {
						right_nullable = true;
					}
					else {
						f_set.right.insert(*it);
					}
				}
				if (right_nullable) {
					nullable = true;
				}
			}
		}
		active.erase(key);

		if (!nullable) {
			return f_set;
		}
		if (i == ss.size() - 1) {
			f_set.right.insert('@');
		}
	}
	return f_set;
}

F_set findFollowInternal(const char non_terminal, const vector<rule>& rules, set<char>& active) {
	F_set f_set;
	f_set.is_first = false;
	f_set.left = string(1, non_terminal);
	f_set.right.insert('#');

	if (active.count(non_terminal)) {
		return f_set;
	}
	active.insert(non_terminal);

	for (size_t i = 0; i < rules.size(); ++i) {
		const rule& current_rule = rules[i];
		for (size_t j = 0; j < current_rule.right.size(); ++j) {
			const string& right_part = current_rule.right[j];
			for (size_t k = 0; k < right_part.size(); ++k) {
				if (right_part[k] != non_terminal) {
					continue;
				}

				if (k + 1 < right_part.size()) {
					string suffix = right_part.substr(k + 1);
					F_set suffix_first = findFirst(suffix, rules);
					bool nullable = false;
					for (set<char>::iterator it = suffix_first.right.begin(); it != suffix_first.right.end(); ++it) {
						if (*it == '@') {
							nullable = true;
						}
						else {
							f_set.right.insert(*it);
